pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 blockNumber, uint256 timestamp) public {
        vm.assume(amount == 10 ether);
        vm.assume(blockNumber > 0);
        vm.assume(timestamp > 0);
        vm.roll(blockNumber);
        vm.warp(timestamp);
        address caller = address(0x1234);
        vm.deal(caller, amount);
        uint256 callerBalanceBefore = caller.balance;
        vm.prank(caller);
        (bool success, ) = address(c).call{value: amount}("");
        if (success && blockNumber % 15 == 0) {
            assertTrue(caller.balance > callerBalanceBefore || (caller.balance == callerBalanceBefore && address(c).balance == 0));
        } else {
            assertTrue(true);
        }
    }
}
